`timescale 1ns/1ps
// Multiplica dois números com sinal de 8 bits usando produtos parciais e somadores estruturais.
module multiplica_com_sinal_8_por_8(input wire signed [7:0] lhs,
    input wire signed [7:0] rhs, output wire signed [15:0] product);
    // Cada bit de rhs seleciona uma linha de produtos parciais de lhs.
    wire [15:0] linha_parcial_0;
    // As portas AND formam os produtos antes da soma das linhas.
    wire [7:0] linha_selecionada_0;
    and (linha_selecionada_0[0], lhs[0], rhs[0]);
    and (linha_selecionada_0[1], lhs[1], rhs[0]);
    and (linha_selecionada_0[2], lhs[2], rhs[0]);
    and (linha_selecionada_0[3], lhs[3], rhs[0]);
    and (linha_selecionada_0[4], lhs[4], rhs[0]);
    and (linha_selecionada_0[5], lhs[5], rhs[0]);
    and (linha_selecionada_0[6], lhs[6], rhs[0]);
    and (linha_selecionada_0[7], lhs[7], rhs[0]);
    wire [15:0] linha_parcial_1;
    wire [7:0] linha_selecionada_1;
    and (linha_selecionada_1[0], lhs[0], rhs[1]);
    and (linha_selecionada_1[1], lhs[1], rhs[1]);
    and (linha_selecionada_1[2], lhs[2], rhs[1]);
    and (linha_selecionada_1[3], lhs[3], rhs[1]);
    and (linha_selecionada_1[4], lhs[4], rhs[1]);
    and (linha_selecionada_1[5], lhs[5], rhs[1]);
    and (linha_selecionada_1[6], lhs[6], rhs[1]);
    and (linha_selecionada_1[7], lhs[7], rhs[1]);
    wire [15:0] linha_parcial_2;
    wire [7:0] linha_selecionada_2;
    and (linha_selecionada_2[0], lhs[0], rhs[2]);
    and (linha_selecionada_2[1], lhs[1], rhs[2]);
    and (linha_selecionada_2[2], lhs[2], rhs[2]);
    and (linha_selecionada_2[3], lhs[3], rhs[2]);
    and (linha_selecionada_2[4], lhs[4], rhs[2]);
    and (linha_selecionada_2[5], lhs[5], rhs[2]);
    and (linha_selecionada_2[6], lhs[6], rhs[2]);
