    and (linha_selecionada_3[4], lhs[4], rhs[3]);
    and (linha_selecionada_3[5], lhs[5], rhs[3]);
    and (linha_selecionada_3[6], lhs[6], rhs[3]);
    and (linha_selecionada_3[7], lhs[7], rhs[3]);
    wire [15:0] linha_parcial_4;
    wire [7:0] linha_selecionada_4;
    and (linha_selecionada_4[0], lhs[0], rhs[4]);
    and (linha_selecionada_4[1], lhs[1], rhs[4]);
    and (linha_selecionada_4[2], lhs[2], rhs[4]);
    and (linha_selecionada_4[3], lhs[3], rhs[4]);
    and (linha_selecionada_4[4], lhs[4], rhs[4]);
