    and (linha_selecionada_5[2], lhs[2], rhs[5]);
    and (linha_selecionada_5[3], lhs[3], rhs[5]);
    and (linha_selecionada_5[4], lhs[4], rhs[5]);
    and (linha_selecionada_5[5], lhs[5], rhs[5]);
    and (linha_selecionada_5[6], lhs[6], rhs[5]);
    and (linha_selecionada_5[7], lhs[7], rhs[5]);
